contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function run(uint dummy) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        uint totalBefore = address(this).balance + address(c).balance;
        c.withdraw(); if (__ESBMC_reverted()) return;
        uint totalMid = address(this).balance + address(c).balance;
        c.withdraw(); if (__ESBMC_reverted()) return;
        assert(c.balances(address(this)) == 0 && totalMid == totalBefore && address(this).balance + address(c).balance == totalBefore);
    }
    receive() external payable {}
}

