// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {keepMyEther} from "../src/keepMyEther.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    keepMyEther c;

    function setUp() public {
        c = new keepMyEther();
    }

    function _run(uint256 dummy) internal {
        vm.deal(address(c), VALUE_CAP);
        uint totalBefore = address(this).balance + address(c).balance;
        try c.withdraw() {} catch { return; }
        uint totalMid = address(this).balance + address(c).balance;
        try c.withdraw() {} catch { return; }
        assertTrue(c.balances(address(this)) == 0 && totalMid == totalBefore && address(this).balance + address(c).balance == totalBefore);
    }

    function testFuzz_run(uint256 dummy) public {
        _run(dummy);
    }

    receive() external payable {}
}
